// ─── ANIMATED COUNTER ───────────────────────────────────────────────────
function useCountUp(target, duration = 1800, delay = 200) {
  const [count, setCount] = useState(0);
  const started = useRef(false);
  useEffect(() => {
    if (started.current) return;
    started.current = true;
    const t = setTimeout(() => {
      const s = performance.now();
      const step = (now) => {
        const p = Math.min((now - s) / duration, 1);
        const e = p === 1 ? 1 : 1 - Math.pow(2, -10 * p);
        setCount(Math.floor(e * target));
        if (p < 1) requestAnimationFrame(step);
      };
      requestAnimationFrame(step);
    }, delay);
    return () => clearTimeout(t);
  }, [target, duration, delay]);
  return count;
}

function fmt(n) {
  if (n >= 1000000) return (n / 1000000).toFixed(1).replace(/\.0$/, "") + "M";
  if (n >= 1000) return (n / 1000).toFixed(1).replace(/\.0$/, "") + "K";
  return n.toString();
}

function AnimStat({ value, label, delay = 200, icon, sub }) {
  const c = useCountUp(value, 2000, delay);
  return (
    <div style={{ textAlign: "center", display: "flex", flexDirection: "column", alignItems: "center", gap: 2 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
        {icon && <span style={{ display: "flex", color: "var(--text-tertiary)" }}>{icon}</span>}
        <span style={{ fontSize: 18, fontWeight: 700, letterSpacing: "-0.03em", fontFamily: "'JetBrains Mono', monospace" }}>{fmt(c)}</span>
      </div>
      <span style={{ fontSize: 11, color: "var(--text-tertiary)", fontWeight: 500 }}>{label}</span>
      {sub && <span style={{ fontSize: 10, color: "var(--text-tertiary)", opacity: 0.7 }}>{sub}</span>}
    </div>
  );
}

