// ─── MAIN ───────────────────────────────────────────────────────────────

function FadeIn({ children, delay = 0 }) {
  const ref = React.useRef(null);
  const [visible, setVisible] = useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) { setVisible(true); obs.disconnect(); }
    }, { threshold: 0.08 });
    obs.observe(el);
    return () => obs.disconnect();
  }, []);
  return (
    <div ref={ref} style={{
      opacity: visible ? 1 : 0,
      transform: visible ? "translateY(0)" : "translateY(18px)",
      transition: `opacity 0.5s ease ${delay}s, transform 0.5s ease ${delay}s`,
    }}>
      {children}
    </div>
  );
}

export default function App() {
  const [dark, setDark] = useState(false);
  const [tab, setTab] = useState("setup");
  const [cat, setCat] = useState("all");
  const [sel, setSel] = useState(null);
  const [selAI, setSelAI] = useState(false);

  const theme = dark ? T.dark : T.light;
  const gear = cat === "all" ? MY_GEAR : MY_GEAR.filter(g => g.category === cat);

  const pick = (item, ai = false) => { setSel(item); setSelAI(ai); window.scrollTo({ top:0,behavior:"smooth" }); };

  if (sel) {
    
  // Scroll animation observer
  React.useEffect(() => {
    const els = document.querySelectorAll('.fu');
    const obs = new IntersectionObserver((entries) => {
      entries.forEach(e => {
        if (e.isIntersecting) {
          e.target.style.animationPlayState = 'running';
          obs.unobserve(e.target);
        }
      });
    }, { threshold: 0.05 });
    els.forEach(el => {
      el.style.animationPlayState = 'paused';
      obs.observe(el);
    });
    return () => obs.disconnect();
  }, [tab]);

  return (
      <><style>{css(theme)}</style>
        <div style={{ background:"var(--bg)",minHeight:"100vh",color:"var(--tx)" }}>
          <div className="ctn"><ProdPage item={sel} onBack={()=>{setSel(null);setSelAI(false)}} ai={selAI} /></div>
        </div>
      </>
    );
  }

  return (
    <><style>{css(theme)}</style>
      <div style={{ background:"var(--bg)",minHeight:"100vh",color:"var(--tx)",paddingBottom:80 }}>
        <div className="ctn">
          <div style={{ display:"flex",justifyContent:"flex-end",padding:"12px 0" }}>
            <button onClick={()=>setDark(!dark)} style={{ background:"var(--bgS)",border:"1px solid var(--bd)",borderRadius:8,width:36,height:36,display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",color:"var(--txS)",transition:"all .2s ease" }}>
              {dark ? <I.Sun /> : <I.Moon />}
            </button>
          </div>

          <Profile dark={dark} />
          <div style={{ height:1,background:"var(--bdL)",margin:"8px 0 24px" }} />

          {tab === "setup" && (
            <section className="fu fu2">
              <SH icon={<I.Eye />} title="My Setup" />
              
              {/* Setup Photo */}
              <div style={{
                width:"100%",aspectRatio:"3/4",borderRadius:12,overflow:"hidden",
                border:"1px solid var(--bdL)",background:"var(--bgT)",marginBottom:16,
                position:"relative",
              }}>
                <img
                  src="data:image/jpeg;base64,"
                  alt="Exosi Setup"
                  style={{ width:"100%",height:"100%",objectFit:"cover" }}
                  onError={e=>{e.target.style.display="none";e.target.parentElement.innerHTML='<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;color:#999;font-size:14px">Setup Photo</div>'}}
                />
              </div>

              {/* ─── SPECS TABS: Peripherals / PC Specs ─── */}
              <SetupTabs onGoGear={() => { setCat("all"); setTab("gear"); window.scrollTo({top:0,behavior:"smooth"}); }} />
            </section>
          )}

          {tab === "gear" && (
            <section className="fu fu2">
              <SH icon={<I.Monitor />} title="My Gear" count={`${MY_GEAR.length} items`} />
              <p style={{ fontSize:13,color:"var(--txS)",marginBottom:12,lineHeight:1.6 }}>
                Tap any item for my review, verdict, and buy link.
              </p>
              <div style={{ marginBottom:16 }}><CatFilter active={cat} onChange={setCat} /></div>
              <div style={{ display:"flex",flexDirection:"column",gap:8 }}>
                {gear.map((item,i) => <div key={item.id} className={`fu fu${Math.min(i+2,5)}`}><ProdCard item={item} onClick={()=>pick(item)} /></div>)}
                {gear.length===0 && <p style={{ fontSize:13,color:"var(--txT)",textAlign:"center",padding:"24px 0" }}>No gear in this category yet.</p>}
              </div>
            </section>
          )}

          {tab === "videos" && (
            <section className="fu fu2">
              <SH icon={<I.Play />} title="Most Viewed Videos" count={`${VIDEOS.length} videos`} />
              <p style={{ fontSize:13,color:"var(--txS)",marginBottom:16,lineHeight:1.6 }}>
                My top performing TikToks — sorted by views. Tap to watch.
              </p>

              <div style={{ display:"flex",flexDirection:"column",gap:10 }}>
                {VIDEOS.map((v, i) => (
                  <a
                    key={v.id}
                    href={v.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className={`fu fu${Math.min(i+2,5)}`}
                    style={{
                      display:"flex",alignItems:"center",gap:14,padding:12,
                      background:"var(--card)",border:"1px solid var(--bdL)",borderRadius:12,
                      textDecoration:"none",color:"var(--tx)",transition:"all .2s ease",
                      boxShadow:"var(--sh)",
                    }}
                    onMouseEnter={e=>{e.currentTarget.style.boxShadow="var(--shH)";e.currentTarget.style.borderColor="var(--bd)"}}
                    onMouseLeave={e=>{e.currentTarget.style.boxShadow="var(--sh)";e.currentTarget.style.borderColor="var(--bdL)"}}
                  >
                    {/* Rank Number */}
                    <div style={{
                      width:32,height:32,minWidth:32,borderRadius:8,
                      background: i === 0 ? "var(--ac)" : "var(--bgT)",
                      color: i === 0 ? "var(--acT)" : "var(--txT)",
                      display:"flex",alignItems:"center",justifyContent:"center",
                      fontSize:13,fontWeight:700,fontFamily:"'JetBrains Mono',monospace",
                    }}>
                      {i + 1}
                    </div>

                    {/* Stats */}
                    <div style={{ flex:1,minWidth:0 }}>
                      {/* Views headline */}
                      <div style={{ display:"flex",alignItems:"center",gap:6,marginBottom:4 }}>
                        <span style={{ display:"flex",color:"var(--txT)" }}><I.Eye /></span>
                        <span className="mono" style={{ fontSize:16,fontWeight:700 }}>{v.views}</span>
                        <span style={{ fontSize:12,color:"var(--txT)" }}>views</span>
                      </div>
                      {/* Sub stats */}
                      <div style={{ display:"flex",alignItems:"center",gap:10,flexWrap:"wrap" }}>
                        <span style={{ display:"flex",alignItems:"center",gap:3,fontSize:12,color:"var(--txS)" }}>
                          <I.Heart /> {v.likes}
                        </span>
                        <span style={{ display:"flex",alignItems:"center",gap:3,fontSize:12,color:"var(--txS)" }}>
                          <I.Bookmark /> {v.saves}
                        </span>
                        <span style={{ display:"flex",alignItems:"center",gap:3,fontSize:12,color:"var(--txS)" }}>
                          <I.Share /> {v.shares}
                        </span>
                      </div>
                    </div>

                    {/* Watch CTA */}
                    <div style={{
                      padding:"6px 12px",borderRadius:8,background:"var(--bgT)",
                      fontSize:12,fontWeight:600,color:"var(--txS)",
                      display:"flex",alignItems:"center",gap:4,whiteSpace:"nowrap",
                    }}>
                      <I.Play /> Watch
                    </div>
                  </a>
                ))}
              </div>

              {/* Follow CTA */}
              <a
                href="https://tiktok.com/@byexosi"
                target="_blank"
                rel="noopener noreferrer"
                style={{
                  display:"flex",alignItems:"center",justifyContent:"center",gap:8,
                  width:"100%",padding:"12px",borderRadius:10,marginTop:16,
                  border:"1px solid var(--bd)",background:"transparent",
                  color:"var(--tx)",fontSize:13,fontWeight:600,
                  textDecoration:"none",fontFamily:"'DM Sans',sans-serif",
                  transition:"all .2s ease",
                }}
              >
                <I.TT /> Follow @byexosi on TikTok
              </a>
            </section>
          )}

          {tab === "deals" && (
            <section className="fu fu2">
              <SH icon={<I.Tag />} title="Deals & Affiliate Codes" />
              <div style={{ display:"flex",flexDirection:"column",gap:8 }}>
                {DEALS.map((d,i) => <div key={d.id} className={`fu fu${Math.min(i+2,5)}`}><DealCard d={d} /></div>)}
              </div>
            </section>
          )}

          {tab === "contact" && (
            <section className="fu fu2">
              <SH icon={<I.Handshake />} title="Work With Me" />
              <ContactSection />
            </section>
          )}

          <div style={{ marginTop:48,textAlign:"center",padding:"32px 0 40px",borderTop:"1px solid var(--bdL)" }}>
            <p style={{ fontSize:11,color:"var(--txT)" }}>byexosi · Latvia · Affiliate links help support my content</p>
          </div>
        </div>
        <Nav active={tab} onChange={setTab} />
      </div>
    </>
  );
}
